/* A local PIN gates worksheet access in the downloadable application. */
(()=>{'use strict';
const $=id=>document.getElementById(id),KEY='kpAdministratorPinV1',TABS=['ayan','lmt','stcalc','raphael5','planet','mdcalc'],LABELS=['Longitude','Local mean time','Sidereal time','Raphael houses','Planet positions','DBA calculations'];let unlocked=false,record=null,idleTimer;
try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw&&raw.iterations===210000&&/^[0-9a-f]{32}$/.test(raw.salt)&&/^[0-9a-f]{64}$/.test(raw.hash))record=raw;}catch(_){}
const tr=x=>KPLanguage?.translate(x)||x,hex=bytes=>[...bytes].map(v=>v.toString(16).padStart(2,'0')).join('');
async function digest(pin,salt){if(!crypto.subtle)throw Error('Open the software in Chrome or Edge to use the administrator PIN.');const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(pin),'PBKDF2',false,['deriveBits']);return hex(new Uint8Array(await crypto.subtle.deriveBits({name:'PBKDF2',salt:Uint8Array.from(salt.match(/../g),s=>parseInt(s,16)),iterations:210000,hash:'SHA-256'},key,256)));}
function equal(a,b){let different=a.length^b.length;for(let i=0;i<a.length;i++)different|=a.charCodeAt(i)^b.charCodeAt(i);return !different;}
function updateReports(){window.renderReport?.();window.KPReportPages?.refresh();}
function lock(){unlocked=false;clearTimeout(idleTimer);document.body.classList.remove('admin-calculations-unlocked');$('admin-calculation-host').hidden=true;$('admin-calculation-controls').hidden=true;$('admin-pin-form').hidden=false;for(const input of $('admin-pin-form').querySelectorAll('input'))input.value='';$('admin-pin-confirm-row').hidden=!!record;$('admin-pin-submit').textContent=tr(record?'Unlock calculations':'Set administrator PIN');updateReports();}
function touch(){if(unlocked){clearTimeout(idleTimer);idleTimer=setTimeout(lock,15*60*1000);}}
function choose(id){if(!unlocked||!TABS.includes(id))return false;for(const tab of TABS)$(tab).classList.toggle('active',tab===id);if(id==='mdcalc')$('dba-worksheet-calculations').open=true;for(const b of document.querySelectorAll('[data-admin-worksheet]'))b.setAttribute('aria-pressed',String(b.dataset.adminWorksheet===id));$('admin-worksheet-title').textContent=tr(LABELS[TABS.indexOf(id)]);touch();return true;}
function init(){const section=$('admin-calculations');section.innerHTML='<article class="admin-window"><header><h2>Administrator calculations</h2></header><form id="admin-pin-form"><label>Administrator PIN<input name="admin-pin" type="password" autocomplete="current-password" minlength="6" maxlength="128" required></label><label id="admin-pin-confirm-row">Confirm PIN<input name="admin-confirm" type="password" autocomplete="new-password" maxlength="128"></label><button id="admin-pin-submit" type="submit">Unlock calculations</button><p id="admin-pin-status" role="status"></p></form><div id="admin-calculation-controls" hidden><div class="admin-worksheet-tabs">'+TABS.map((id,i)=>'<button type="button" data-admin-worksheet="'+id+'">'+LABELS[i]+'</button>').join('')+'<button id="admin-pin-lock" type="button">Lock calculations</button></div><h3 id="admin-worksheet-title"></h3></div><div id="admin-calculation-host" hidden></div></article>';
 // Keep original input IDs and calculation handlers; only regroup their UI.
 for(const id of TABS)$('admin-calculation-host').append($(id));
 const render=window.renderReport;window.renderReport=function(...args){const result=render.apply(this,args);if(!unlocked)for(const page of $('printReport').querySelectorAll('[data-report-section]'))if(TABS.includes(page.dataset.reportSection))page.remove();return result;};
 for(const id of TABS.slice(0,5))document.querySelectorAll('.app-sidebar [data-tab="'+id+'"],#quick-'+id+',#help-go-'+id).forEach(n=>{n.hidden=true;n.dataset.hiddenRoute='true';n.dataset.adminRoute='true';});
 $('admin-pin-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,pin=form.elements['admin-pin'].value,confirm=form.elements['admin-confirm'].value,button=$('admin-pin-submit');button.disabled=true;
  try{if(pin.length<6)throw Error('Use at least six characters for the administrator PIN.');if(!record){if(pin!==confirm)throw Error('The PINs do not match.');const salt=hex(crypto.getRandomValues(new Uint8Array(16))),hash=await digest(pin,salt);const next={salt,hash,iterations:210000};localStorage.setItem(KEY,JSON.stringify(next));record=next;}else if(!equal(await digest(pin,record.salt),record.hash))throw Error('Incorrect administrator PIN.');
   unlocked=true;document.body.classList.add('admin-calculations-unlocked');form.hidden=true;for(const input of form.querySelectorAll('input'))input.value='';$('admin-pin-status').textContent='';$('admin-calculation-host').hidden=false;$('admin-calculation-controls').hidden=false;choose('ayan');updateReports();
  }catch(error){$('admin-pin-status').textContent=tr(error.message);}finally{button.disabled=false;}
 });
 section.addEventListener('click',e=>{const b=e.target.closest('[data-admin-worksheet]');if(b)choose(b.dataset.adminWorksheet);});$('admin-pin-lock').addEventListener('click',lock);
 // Legacy shortcuts also have to enter the administrator gate.
 document.addEventListener('click',e=>{const route=e.target.closest('[data-tab],[data-go]');if(!route)return;const id=route.dataset.tab||route.dataset.go;if(!TABS.slice(0,5).includes(id))return;e.preventDefault();e.stopImmediatePropagation();document.querySelector('.app-sidebar [data-tab="admin-calculations"]').click();if(unlocked)choose(id);},true);
 new MutationObserver(()=>{if(!section.classList.contains('active'))lock();}).observe(section,{attributes:true,attributeFilter:['class']});for(const event of ['pointerdown','keydown'])section.addEventListener(event,touch);
 if(window.KPProtectedWorker){section.dataset.privateCalculation='true';document.querySelectorAll('[data-tab="admin-calculations"],#quick-admin-calculations').forEach(n=>n.dataset.privateCalculation='true');}
 lock();window.KPLanguage?.localize(section);
}
window.KPAdminCalculations=Object.freeze({lock,select:choose,isUnlocked:()=>unlocked});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,0));else init();
})();
